-- For databases created from the previous experimental project. Review/back up before applying.
ALTER TABLE "Detection" ADD COLUMN IF NOT EXISTS "publishedAt" TIMESTAMP(3),ADD COLUMN IF NOT EXISTS "sourceUpdatedAt" TIMESTAMP(3),ADD COLUMN IF NOT EXISTS "dateConfidence" TEXT NOT NULL DEFAULT 'UNKNOWN',ADD COLUMN IF NOT EXISTS "eventType" TEXT NOT NULL DEFAULT 'NEW';
CREATE TABLE IF NOT EXISTS "TemporalPreference" ("monitorId" UUID PRIMARY KEY,"dateBasis" TEXT NOT NULL DEFAULT 'PUBLISHED',"lookbackDays" INTEGER NOT NULL DEFAULT 7,"since" TIMESTAMP(3),"onlyNew" BOOLEAN NOT NULL DEFAULT TRUE,"notifyUpdates" BOOLEAN NOT NULL DEFAULT TRUE,"requireVerifiedDate" BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT "TemporalPreference_monitorId_fkey" FOREIGN KEY ("monitorId") REFERENCES "Monitor"("id") ON DELETE CASCADE ON UPDATE CASCADE);
